// App icon picker (2026-10-18). Data-driven registry: add an entry + a folder public/icons/<id>/ with
// icon-192/512 (rounded, purpose any), maskable-192/512, apple-180, fav-32, mark-64 (in-app logo) and
// manifest.webmanifest (generated by work/icons-src/compose.py + the manifest step in README). 'auto' = Sky by day, Night by night (HKT).
// Persistence: per device (localStorage nest.icon) first, then the user's profile (prefs.appIcon) as the default on a new device.
import { useEffect, useState } from 'react';

export const ICONS = [
  { id: 'sky', theme: '#7fb6e6' },
  { id: 'night', theme: '#141b3c' },
  { id: 'classic', theme: '#1b1c1f' },
  { id: 'anime', theme: '#3f9cf0' },
  { id: 'japan', theme: '#f4d9d4' },
  { id: 'sunset', theme: '#e9784f' },
  { id: 'mono', theme: '#0a0a0a' },
  { id: 'neon', theme: '#1a0b24' },
];
export const ICON_IDS = ICONS.map((i) => i.id);
export const DEFAULT_ICON = 'sky';
export const AUTO = 'auto';
const KEY = 'nest.icon';
export const iconPath = (id, file) => `/icons/${ICON_IDS.includes(id) ? id : DEFAULT_ICON}/${file}`;
export const validChoice = (c) => c === AUTO || ICON_IDS.includes(c);

const hkHour = (now = Date.now()) => Number(new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Hong_Kong', hour: '2-digit', hour12: false }).format(new Date(now))) % 24;
export function resolveIcon(choice, now = Date.now()) {
  if (choice === AUTO) { const h = hkHour(now); return h >= 6 && h < 18 ? 'sky' : 'night'; }
  return ICON_IDS.includes(choice) ? choice : DEFAULT_ICON;
}
export function readChoice() {
  try { const v = localStorage.getItem(KEY); if (validChoice(v)) return v; } catch {}
  return DEFAULT_ICON;
}
export const hasDeviceChoice = () => { try { return validChoice(localStorage.getItem(KEY)); } catch { return false; } };

function setLink(rel, href, extra = {}) {
  const sel = `link[rel="${rel}"]${extra.sizes ? `[sizes="${extra.sizes}"]` : ''}${extra.type ? `[type="${extra.type}"]` : ''}`;
  let el = document.head.querySelector(sel);
  if (!el) { el = document.createElement('link'); el.rel = rel; if (extra.sizes) el.sizes = extra.sizes; if (extra.type) el.type = extra.type; document.head.appendChild(el); }
  if (el.getAttribute('href') !== href) el.setAttribute('href', href);
}
// Updates favicon, apple-touch-icon, manifest and theme-color for the resolved icon.
export function applyIcon(choice = readChoice(), now = Date.now()) {
  if (typeof document === 'undefined') return DEFAULT_ICON;
  const id = resolveIcon(choice, now);
  if (id === DEFAULT_ICON && choice !== AUTO && !hasDeviceChoice()) return id; // untouched default: keep the static tags
  document.head.querySelectorAll('link[rel="icon"][type="image/svg+xml"]').forEach((l) => l.remove()); // browsers prefer the SVG one
  setLink('icon', iconPath(id, 'fav-32.png'), { sizes: '32x32' });
  setLink('apple-touch-icon', iconPath(id, 'apple-180.png'), { sizes: '180x180' });
  document.head.querySelectorAll('link[rel="apple-touch-icon-precomposed"]').forEach((l) => l.setAttribute('href', iconPath(id, 'apple-180.png')));
  setLink('manifest', iconPath(id, 'manifest.webmanifest'));
  document.documentElement.dataset.appIcon = id;
  return id;
}
export function saveChoice(choice) {
  if (!validChoice(choice)) return;
  try { localStorage.setItem(KEY, choice); } catch {}
  applyIcon(choice);
  window.dispatchEvent(new CustomEvent('nest:icon', { detail: choice }));
}
// { choice, id } — re-resolves 'auto' every 5 minutes and on every change.
export function useAppIcon() {
  const [choice, setChoice] = useState(readChoice);
  const [tick, setTick] = useState(0);
  useEffect(() => {
    const f = (e) => setChoice(validChoice(e.detail) ? e.detail : readChoice());
    window.addEventListener('nest:icon', f);
    const i = setInterval(() => setTick((n) => n + 1), 5 * 60e3);
    return () => { window.removeEventListener('nest:icon', f); clearInterval(i); };
  }, []);
  useEffect(() => { if (choice === AUTO) applyIcon(choice); }, [tick, choice]);
  return { choice, id: resolveIcon(choice) };
}
